// Endpoints: autogenerated (endpoints/auto_<table>.json) and custom (endpoints/<table>.json).
import { api, esc, attempt, dialog, confirmAction, method, callApi, statusClass, json, session, toast } from "../ui.js";

let state = { endpoints: [], errors: [], prefix: "/api", filter: "", open: null };

export async function render(main, app) {
  state.prefix = app.status.apiPrefix;
  main.innerHTML = `
    <h1>Endpoints</h1>
    <div class="sa-toolbar">
      <button class="ez-button" type="button" id="generate">Generate the autogenerated endpoints</button>
      <button class="ez-button ez-button--secondary" type="button" id="new">New custom endpoint</button>
      <span class="sa-toolbar__spacer"></span>
      <label for="filter" class="sa-muted">Table</label>
      <select id="filter"><option value="">All</option></select>
    </div>
    <div id="errors"></div>
    <div id="list"></div>`;

  if (app.status.database.error) {
    main.querySelector("#list").innerHTML = `<div class="ez-alert ez-alert--warning">Connect to the database first, in <a href="#/database">Database</a>.</div>`;
  }

  main.querySelector("#generate").addEventListener("click", async () => {
    const ok = await confirmAction("Generate the endpoints",
      "The files endpoints/auto_<table>.json are written again from the database schema (and the JS API in web/js/api/_auto/). " +
      "Your changes to those files are lost; the custom endpoints (endpoints/<table>.json) are kept and not generated again.", "Generate");
    if (!ok) return;
    const res = await attempt(() => api("/endpoints/generate", "POST", {}));
    if (res) {
      const n = res.tables.reduce((acc, t) => acc + t.generated.length, 0);
      toast(`${n} endpoints generated for ${res.tables.length} tables and views`, "success");
      await app.refreshStatus();
      load(main);
    }
  });
  main.querySelector("#new").addEventListener("click", () => edit(main, null));
  main.querySelector("#filter").addEventListener("change", (e) => {
    state.filter = e.target.value;
    draw(main);
  });
  await load(main);
}

async function load(main) {
  const res = await attempt(() => api("/endpoints"));
  if (!res) return;
  state.endpoints = res.endpoints;
  state.errors = res.errors;
  const tables = [...new Set(res.endpoints.map((e) => e.table))].sort();
  main.querySelector("#filter").innerHTML = `<option value="">All</option>` +
    tables.map((t) => `<option ${t === state.filter ? "selected" : ""}>${esc(t)}</option>`).join("");
  draw(main);
}

function draw(main) {
  main.querySelector("#errors").innerHTML = state.errors.length
    ? `<div class="ez-alert ez-alert--error"><strong>Endpoints not loaded</strong>
        <ul>${state.errors.map((e) => `<li>${esc(e)}</li>`).join("")}</ul></div>` : "";

  const eps = state.endpoints.filter((e) => !state.filter || e.table === state.filter);
  const list = main.querySelector("#list");
  if (!eps.length) {
    if (!list.innerHTML) {
      list.innerHTML = `<p class="sa-muted">No endpoints yet: generate them from the database schema.</p>`;
    }
    return;
  }
  const byTable = {};
  for (const e of eps) {
    (byTable[e.table] ??= []).push(e);
  }
  list.innerHTML = Object.entries(byTable).sort().map(([table, items]) => `
    <section class="sa-section">
      <h2>${esc(table)}</h2>
      <div class="ez-scroll"><table class="sa-table">
        <thead><tr><th>Method</th><th>Route</th><th>Access</th><th>File</th><th></th></tr></thead>
        <tbody>${items.map(row).join("")}</tbody>
      </table></div>
    </section>`).join("");

  for (const button of list.querySelectorAll("[data-action]")) {
    const ep = state.endpoints.find((e) => e.method + " " + e.route === button.dataset.key);
    button.addEventListener("click", () => actions[button.dataset.action](main, ep, button));
  }
}

function row(e) {
  const key = esc(e.method + " " + e.route);
  const access = e.auth_required || e.owner
    ? `logged${e.allowed_roles.includes("*") ? "" : ": " + esc(e.allowed_roles.join(", "))}${e.owner ? `<br>owner: <code>${esc(e.owner)}</code>` : ""}`
    : `<span class="sa-muted">public</span>`;
  const badge = e.source === "auto" ? `<span class="ez-badge">auto</span>` : `<span class="ez-badge ez-badge--primary">custom</span>`;
  const warnings = e.warnings.length ? `<br><span class="sa-small" style="color: var(--ez-warning)">⚠ ${esc(e.warnings.join("; "))}</span>` : "";
  const open = state.open === e.method + " " + e.route;
  return `
    <tr class="${open ? "sa-open" : ""}">
      <td>${method(e.method)}</td>
      <td><span class="sa-route">${esc(state.prefix + e.route)}</span><br><span class="sa-muted sa-small">${esc(e.description)}</span>${warnings}</td>
      <td class="sa-small">${access}</td>
      <td class="sa-small">${badge}<br>${esc(e.file)}</td>
      <td class="sa-actions">
        <button class="ez-button sa-button--small" type="button" data-action="try" data-key="${key}">Try</button>
        ${e.source === "auto"
          ? `<button class="ez-button ez-button--secondary sa-button--small" type="button" data-action="customize" data-key="${key}">Customize</button>`
          : `<button class="ez-button ez-button--secondary sa-button--small" type="button" data-action="edit" data-key="${key}">Edit</button>
             <button class="ez-button ez-button--danger sa-button--small" type="button" data-action="remove" data-key="${key}">Delete</button>`}
      </td>
    </tr>
    ${open ? `<tr class="sa-open"><td colspan="5">${tryForm(e)}</td></tr>` : ""}`;
}

const actions = {
  try(main, ep) {
    const key = ep.method + " " + ep.route;
    state.open = state.open === key ? null : key;
    draw(main);
    if (state.open) {
      bindTry(main, ep);
    }
  },
  async customize(main, ep) {
    const ok = await confirmAction("Customize the endpoint",
      `${ep.method} ${ep.route} moves from ${ep.file} to ${ep.table}.json, where you can change it. ` +
      "Generating the endpoints again will not overwrite it.", "Move to custom");
    if (!ok) return;
    const res = await attempt(() => api("/endpoints/customize", "POST", { method: ep.method, route: ep.route }));
    if (res) {
      toast(`Moved to endpoints/${res.file}`, "success");
      await load(main);
      const moved = state.endpoints.find((e) => e.method === ep.method && e.route === ep.route);
      if (moved) edit(main, moved);
    }
  },
  edit(main, ep) {
    edit(main, ep);
  },
  async remove(main, ep) {
    if (await confirmAction("Delete the endpoint", `${ep.method} ${ep.route} is removed from ${ep.file}.`, "Delete")) {
      if (await attempt(() => api("/endpoints/custom", "DELETE", { file: ep.file, name: ep.name }), "Deleted")) {
        load(main);
      }
    }
  },
};

async function edit(main, ep) {
  const e = ep ?? { name: "", file: (state.filter || "my_table") + ".json", method: "GET", route: "/", sql: "SELECT * FROM ",
    auth_required: false, allowed_roles: ["*"], description: "", request_body_params: [], owner: "" };
  const v = await dialog(ep ? `Edit ${ep.method} ${ep.route}` : "New custom endpoint", `
    <div class="sa-form sa-form--wide">
      <div class="ez-field"><label for="ep-name">Name</label><input id="ep-name" name="name" value="${esc(e.name)}" required pattern="\\w+"></div>
      <div class="ez-field"><label for="ep-file">File (endpoints/)</label><input id="ep-file" name="file" value="${esc(e.file)}" required pattern="[\\w-]+\\.json"></div>
      <div class="ez-field"><label for="ep-method">Method</label><select id="ep-method" name="method">
        ${["GET", "POST", "PUT", "DELETE"].map((m) => `<option ${m === e.method ? "selected" : ""}>${m}</option>`).join("")}</select></div>
      <div class="ez-field sa-span"><label for="ep-route">Route (after ${esc(state.prefix)}; params with $)</label>
        <input id="ep-route" name="route" value="${esc(e.route)}" required></div>
      <div class="ez-field sa-span"><label for="ep-sql">SQL ($params from the route, the body and $loggedId)</label>
        <textarea id="ep-sql" name="sql" class="sa-code" required>${esc(e.sql)}</textarea></div>
      <div class="ez-field sa-span"><label for="ep-body">Body params (comma-separated, for POST and PUT)</label>
        <input id="ep-body" name="request_body_params" value="${esc((e.request_body_params || []).join(", "))}"></div>
      <div class="ez-field"><label><input type="checkbox" name="auth_required" ${e.auth_required ? "checked" : ""}> Requires a session</label></div>
      <div class="ez-field"><label for="ep-roles">Allowed roles (* any)</label><input id="ep-roles" name="allowed_roles" value="${esc((e.allowed_roles || ["*"]).join(", "))}"></div>
      <div class="ez-field"><label for="ep-owner">Owner column (optional)</label><input id="ep-owner" name="owner" value="${esc(e.owner || "")}"
        title="Only the user whose id is in this column can modify or delete the row; in a POST, it is set to the logged user"></div>
      <div class="ez-field sa-span"><label for="ep-desc">Description</label><input id="ep-desc" name="description" value="${esc(e.description)}"></div>
    </div>`, "Save");
  if (!v) return;
  const list = (s) => s.split(",").map((x) => x.trim()).filter(Boolean);
  const data = { description: v.description, route: v.route, method: v.method, sql: v.sql,
    auth_required: v.auth_required, allowed_roles: list(v.allowed_roles).length ? list(v.allowed_roles) : ["*"] };
  if (list(v.request_body_params).length) data.request_body_params = list(v.request_body_params);
  if (v.owner.trim()) data.owner = v.owner.trim();
  const saved = await attempt(() => api("/endpoints/custom", "PUT",
    { file: v.file, name: v.name, oldName: ep?.name, data }), "Saved in endpoints/" + v.file);
  if (saved) {
    load(main);
  } else {
    // Reopen with the values entered, so they are not lost
    edit(main, { ...e, ...data, name: v.name, file: v.file, owner: v.owner,
      request_body_params: list(v.request_body_params), allowed_roles: list(v.allowed_roles) });
  }
}

function tryForm(e) {
  const params = [...e.route.matchAll(/\$(\w+)/g)].map((m) => m[1]);
  const body = e.request_body_params?.length ? JSON.stringify(Object.fromEntries(e.request_body_params.map((p) => [p, ""])), null, 2) : "";
  const current = session.get();
  return `
    <form class="sa-panel" id="try-form">
      <div class="sa-form">
        ${params.map((p) => `<div class="ez-field"><label for="try-${esc(p)}">$${esc(p)}</label><input id="try-${esc(p)}" name="${esc(p)}" required></div>`).join("")}
        ${e.method === "GET" ? `<div class="ez-field"><label for="try-query">Query string</label><input id="try-query" name="__query" placeholder="_sort=title&_limit=5"></div>` : ""}
      </div>
      ${e.method === "POST" || e.method === "PUT" ? `<div class="ez-field"><label for="try-body">Body (JSON)</label>
        <textarea id="try-body" name="__body" class="sa-code">${esc(body)}</textarea></div>` : ""}
      <div class="sa-toolbar">
        <button class="ez-button" type="submit">Send ${esc(e.method)}</button>
        <span class="sa-muted sa-small">${current ? `As <strong>${esc(current.label)}</strong>` : "Without a session"} ·
          <a href="#/users">choose a user</a></span>
      </div>
      <div id="try-result"></div>
    </form>`;
}

function bindTry(main, ep) {
  const form = main.querySelector("#try-form");
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const v = Object.fromEntries(new FormData(form));
    let path = ep.route;
    for (const [k, value] of Object.entries(v)) {
      if (!k.startsWith("__")) path = path.replace("$" + k, encodeURIComponent(value));
    }
    if (v.__query) path += "?" + v.__query.replace(/^\?/, "");
    let body;
    if (v.__body?.trim()) {
      try {
        body = JSON.parse(v.__body);
      } catch {
        toast("The body is not valid JSON", "error");
        return;
      }
    }
    const res = await attempt(() => callApi(state.prefix, ep.method, path, body));
    if (!res) return;
    form.querySelector("#try-result").innerHTML = `
      <p><span class="sa-status ${statusClass(res.status)}">${res.status}</span>
        <span class="sa-muted">${esc(ep.method)} ${esc(state.prefix + path)} · ${res.ms} ms
        ${Array.isArray(res.data) ? ` · ${res.data.length} rows` : ""}</span></p>
      <pre class="sa-pre">${json(res.data)}</pre>`;
  });
}
